from pathlib import Path
import json,csv,re

OUT=Path(__file__).parent
talks=[];items=[];problems=[];corrections=[];areas={};refs={}
def talk(record,date,speaker,pages,title,summary,kind='talk'):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))
def item(record,pages,kind,title,notes,statement,cls,fate,keys=(),reconstruction='',literal='correct with missing hypotheses',match='partial',verification='read the result',confidence='high',problem='',worth='',speaker='',area='',development='annotated',status=''):
    num=1+sum(i['record']==record for i in items); ident=f'1977-{record}.{num}'
    o=dict(id=ident,record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status=status or ('As of 10 November 2026: '+('established in the stated scope; the notebook is exposition of this result.' if cls=='E' else 'the stated construction is established; the qualifications above are essential.' if cls in 'AB' else 'the surviving wording does not determine a theorem with all hypotheses.')),literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(keys),confidence=confidence)
    if speaker:o['speaker']=speaker
    items.append(o); areas[ident]=area or ('Algebraic geometry and homological algebra' if record==438 else 'Mathematical physics' if record in (439,442,443) else 'Special functions and arrangements' if record==440 else 'Topology and Lie cohomology' if record in (441,444) else 'Foundations and surreal numbers' if record==445 else 'Representation theory' if record==451 else 'Lie theory and mathematical physics')
    return ident
def problem(ident,title,statement,occurrences,status,keys=()):problems.append(dict(id=ident,title=title,statement=statement,occurrences=occurrences,status=status,status_date='2026-11',refs=list(keys)))
def correction(page,place,reads,should,evidence,applies='both',kind='faithful_error'):corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=kind))
def clean_prose(s):
    words='in|of|to|by|the|and|are|all|for|has|from|into|only|over|than|is|as|modulo|these|this|later|adjacent|dated|date|reads|received|submitted|published|Theorem|Theorems|Section|Sections|Chapter|dimension|weight|weights|degree|degrees|rank|factor|frequency|depth|exact|September|October|November|December|January|February|March|April|May|June|July|August'
    months='January|February|March|April|May|June|July|August|September|October|November|December'
    s=re.sub(r'\b('+words+r')(?=\d)',r'\1 ',s)
    s=re.sub(r'(\d)('+months+r')',r'\1 \2',s)
    s=re.sub(r"'s(?=\d)","'s ",s)
    return s

