def save():
    for obj in talks+items+problems:
        for field in ('summary','notes','statement','reconstruction','fate','present_status','worth','status'):
            if field in obj:obj[field]=clean_prose(obj[field])
    repair_correction_latex(corrections)
    for row in corrections:
        for field in ('place','transcription_reads','should_read','evidence'):
            row[field]=clean_prose(row[field])
    for name,obj in [('talks',talks),('items',items),('problems',problems),('areas',areas)]:
        (OUT/(name+'.json')).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
    with (OUT/'corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)

talk(438,'1978-02-27','S. I. Gelfand','P000753-P000754; P000756-P000762','Exterior algebra modules, projective bundles, and derived categories',r'''The principal lecture starts on P000757, dated 27 February 1978. P000753--P000754 and P000756 preserve a preceding lecture of 13 February 1978, absent as a separate record from the supplied list; they are included here as explicitly adjacent evidence, not assigned to Faddeev. Both lectures explain the construction later called the Bernstein--Gelfand--Gelfand correspondence: a finite graded exterior-algebra module gives a linear complex of twists on projective space, and suitable modules describe vector bundles modulo free summands. The second lecture develops symmetric/exterior Koszul functors and the language of derived categories. Several displayed formulas are faithfully defective: the total differential lacks a sign, and the proposed unit map vanishes on a trivial module.''')
item(438,'P000753','remark','Topoi and derived categories as organizing concepts',r'''I. M. Gelfand singles out the topos and the derived category as two primary categorical concepts.''',r'''This is a methodological comparison, not a classification or universal-property theorem: a topos organizes sheaf-theoretic localization, while a derived category records complexes up to quasi-isomorphism.''','E',r'''The latter framework was already developed in the Harvard seminar of 1963--1964, published as \citet[Chapter~I]{hartshorne1966residues}.''',['hartshorne1966residues'],reconstruction='The explanatory distinction is editorial; the notebook only lists the two concepts.',literal='correct',verification='publisher metadata checked',speaker='I. M. Gelfand')
item(438,'P000753; P000757-P000758','definition','Graded exterior modules and evaluation complexes',r'''\(\Lambda=\Lambda(\Xi)\), \(\dim\Xi=n+1\), \(\deg\xi_i=-1\), and \(V=\bigoplus V_j\) is finite-dimensional. Multiplication by any \(0\ne\xi\in\Xi\) makes \(\cdots\to V_1\to V_0\to V_{-1}\to\cdots\) a complex because \(\xi^2=0\).''',r'''Over \(\mathbb C\), the exterior algebra of an \((n+1)\)-dimensional vector space has \(\dim\Lambda_{-k}=\binom{n+1}{k}\). For a finite graded left module, the maps \(v\mapsto\xi v\) have degree \(-1\) and square zero. A module is called proper here when its evaluation complex has homology only in degree zero for every nonzero \(\xi\).''','A',r'''The same definitions precede Theorem~1 of \citet{bernsteingelfandgelfand1978bundles}; submitted 10 January 1978, published in Russian later in 1978.''',['bernsteingelfandgelfand1978bundles'],match='exact',literal='correct')
item(438,'P000754; P000759','claim','Constant rank and the bundle of evaluation homology',r'''For proper \(V\), \(\dim H_0(L_\xi(V))\) is constant by the Euler characteristic; these spaces form a bundle.''',r'''For a finite complex with all fiber homology except degree zero vanishing, the remaining dimension is the alternating sum of the dimensions of the terms, hence is independent of the projective point. The cohomology sheaf of the associated locally free complex is locally free and commutes with taking fibers.''','A',r'''This is the well-definedness step for \(\Phi(V)\) in \citet[Section~3]{bernsteingelfandgelfand1978bundles}.''',['bernsteingelfandgelfand1978bundles'],match='exact',reconstruction='The local-freeness and base-change assertion is stated explicitly here; a constant Euler characteristic by itself would not suffice without the other fiber cohomology vanishing.')
item(438,'P000754','claim','Free exterior modules produce the zero bundle',r'''The regular module and its shifts have zero evaluation homology. The subsequent sentence says that free modules give a \ru{тривиальное расслоение}.''',r'''For \(0\ne\xi\), choose \(\ell\in\Xi^*\) with \(\ell(\xi)=1\); contraction by \(\ell\) contracts multiplication by \(\xi\). Thus every finite graded free \(\Lambda\)-module gives an acyclic complex, hence the rank-zero bundle, not an arbitrary positive-rank trivial bundle.''','A',r'''Acyclicity of free modules is used in \citet[Section~3]{bernsteingelfandgelfand1978bundles}.''',['bernsteingelfandgelfand1978bundles'],match='exact',reconstruction='The contraction proof and explicit rank-zero wording clarify the notebook. No new theorem is claimed.',literal='false as written')
item(438,'P000754; P000759','theorem','Stable exterior-module description of algebraic vector bundles',r'''Every algebraic bundle is \(\Phi(V)\), and \(\Phi(V)\cong\Phi(V')\) iff \(V\oplus P\cong V'\oplus P'\) for free modules. The notes credit Bernstein and both Gelfands, and mention an independent related result of Beilinson.''',r'''For \(\mathbb P^n_{\mathbb C}\), isomorphism classes of algebraic vector bundles are in bijection with stable isomorphism classes of finite graded proper \(\Lambda(\mathbb C^{n+1})\)-modules. Stabilization is by finite sums of grading shifts of the regular module.''','A',r'''Exact match: \citet[Theorem~1]{bernsteingelfandgelfand1978bundles}. This is a reduction to module classification, not a list of all bundle moduli.''',['bernsteingelfandgelfand1978bundles'],match='exact',literal='correct',problem='GP-1977-41')
problem('GP-1977-41','Describe projective bundles by finite exterior modules',r'''Can algebraic vector bundles on \(\mathbb P^n\) be represented and compared by finite-dimensional graded modules over an exterior algebra? The notebook's broad classification question is indexed in the specific form answered by its theorem.''',['1977-438.5'],r'''As of November 2026, the representation and stable-isomorphism criterion are established by BGG. A full explicit moduli classification is a different, substantially broader question and is not claimed solved here.''',['bernsteingelfandgelfand1978bundles'])
item(438,'P000754; P000758','definition','The twisting sheaf and its local rank-one property',r'''Three definitions of \(O(j)\) are offered: transition functions, homogeneous degree-\(j\) rational functions, and powers of the anti-Hopf bundle. An exercise asks why the resulting bundle is one-dimensional.''',r'''For a Zariski-open \(U\subset\mathbb P^n\), sections of \(O(j)\) are homogeneous rational functions of degree \(j\) regular on the inverse image of \(U\) in \(\mathbb C^{n+1}\setminus\{0\}\). On \(x_i\ne0\), multiplication by \(x_i^{-j}\) identifies this module with \(O_U\), proving local rank one. Negative powers mean dual tensor powers.''','E',r'''The twisting sheaves and homogeneous-module construction are classical: \citet[Chapter~III]{serre1955coherent}.''',['serre1955coherent'],match='exact',problem='GP-1977-42',reconstruction='The topology and omission of the cone vertex are necessary. Regular algebraic sections, rather than arbitrary analytic sections, are intended.')
problem('GP-1977-42','Why homogeneous functions define a line bundle',r'''Why do homogeneous rational functions of integer degree \(j\), regular above a projective open set, form a locally free sheaf of rank one?''',['1977-438.6'],r'''Resolved classically: division by \(x_i^j\) gives an explicit local trivialization on \(x_i\ne0\). This is an exercise, not an open research question.''',['serre1955coherent'])
item(438,'P000754; P000758','construction','The linear sheaf complex associated with an exterior module',r'''\(\mathcal L^j=V_{-j}\otimes O(j)\) and \((df)(\xi)=\xi f(\xi)\).''',r'''The tautological section defines maps \(V_{-j}\otimes O(j)\to V_{-j-1}\otimes O(j+1)\). The exterior relations give \(d^2=0\); the construction is independent of a basis of \(\Xi\).''','A',r'''This is precisely \(L(V)\) in \citet[Section~3]{bernsteingelfandgelfand1978bundles}.''',['bernsteingelfandgelfand1978bundles'],match='exact',literal='correct')
item(438,'P000756','method','A truncated Koszul kernel followed by syzygies',r'''The page starts mid-proof: \(C_N\otimes\Lambda\to C_{N+1}\otimes\Lambda\), \(c\otimes\lambda\mapsto\sum X_i(c)\otimes\xi_i\lambda\); take its kernel and then \(N\) free-kernel steps with grading shifts.''',r'''If \(C\) is a graded module over \(S=\mathbb C[x_0,\ldots,x_n]\), multiplication by the coordinate functions gives the displayed basis-independent linear map. For sufficiently high truncation and suitable grading conventions, a Koszul-dual module may be recovered using successive syzygies.''','A',r'''The structural inverse belongs to the BGG equivalence, \citet[Theorem~2]{bernsteingelfandgelfand1978bundles}; this page's precise normalization is only partially matched.''',['bernsteingelfandgelfand1978bundles'],reconstruction='The missing preceding P000755 is not attached. C, the admissible bound on N, and the exact shift cannot be recovered from P000756 alone; no unique explicit inverse is asserted.',confidence='medium')
item(438,'P000756; P000759','theorem',"Serre's quotient-category description of coherent sheaves",r'''Gelfand urges replacing bundles by sheaves, since bundles do not form an abelian category. Coherent sheaves on projective space correspond to finitely generated graded polynomial modules modulo finitely many components.''',r'''For \(S=\mathbb C[x_0,\ldots,x_n]\), sheafification induces \(\operatorname{grmod}(S)/\operatorname{tors}(S)\simeq\operatorname{Coh}(\mathbb P^n)\), where torsion means finite-dimensional graded modules. A representative is \(\bigoplus_{j\ge N}H^0(\mathcal E(j))\) for sufficiently large \(N\).''','E',r'''\citet[Chapter~III]{serre1955coherent} is the relevant 1955 publication; the notebook's 1953 bibliographic date is inaccurate.''',['serre1955coherent'],match='exact',reconstruction='Truncation avoids claiming the unbounded section module is finitely generated for every coherent sheaf; e.g. a skyscraper has sections in every negative twist.')
item(438,'P000756','construction','Sheafification by degree-zero localization',r'''On \(E_i=\{x_i\ne0\}\), sections are fractions \(m/x_i^s\) with \(\deg m=s\). The grading shift of \(S\) gives \(O(N)\).''',r'''For a graded \(S\)-module \(M\), define \(\widetilde M(D_+(x_i))=(M_{x_i})_0\) and glue by the canonical localization maps. With \(M(N)_j=M_{j+N}\), \(\widetilde{S(N)}=O(N)\).''','E',r'''This is Serre's sheafification construction; see \citet[Chapter~III]{serre1955coherent}.''',['serre1955coherent'],match='exact',literal='correct')
item(438,'P000759','construction','The symmetric-algebra linear complex',r'''\(W^k=V_{-k}\otimes S\), \(d(v\otimes s)=\sum\xi_i v\otimes x_i s\), and \((W^k)_j=V_{-k}\otimes S_{j+k}\).''',r'''The differential is homogeneous of internal degree zero and cohomological degree one; its square vanishes because the \(x_i\) commute and the \(\xi_i\) anticommute. Sheafifying this complex recovers \(\mathcal L(V)\).''','A',r'''This is the polynomial form of the functor in \citet[Sections~3--4]{bernsteingelfandgelfand1978bundles}.''',['bernsteingelfandgelfand1978bundles'],match='exact',literal='correct')
item(438,'P000760','construction','Totalization and the missing Koszul sign',r'''For a complex \((V^i,\partial)\), the written total differential is \(\partial\otimes1+\sum\xi_i\otimes x_i\), with a visible plus but no sign.''',r'''For commuting bicomplex differentials \(d_h,d_v\), totalize using \(d_{\rm tot}=d_h+(-1)^p d_v\) on horizontal degree \(p\). Equivalently first impose an anticommuting bicomplex convention. Without either convention the displayed sum need not square to zero in characteristic zero.''','E',r'''Totalization conventions are part of the pre-existing derived-category apparatus; \citet[Chapter~I]{hartshorne1966residues}.''',['hartshorne1966residues'],literal='false as written',verification='publisher metadata checked',reconstruction='The required sign is an editorial repair, not a newly read mark in the manuscript.')
item(438,'P000760','construction','The Hom Koszul-dual functor',r'''\(V=\operatorname{Hom}_{\mathbb C}(\Lambda,W)\), with a regrading, and \(\partial(v)(\lambda)=d(v(\lambda))+\sum x_i v(\xi_i\lambda)\).''',r'''The reverse Koszul functor uses the graded Hom complex from \(\Lambda\) into a complex of graded \(S\)-modules, with differential combining the original differential and the contraction induced by \(\sum x_i\otimes\xi_i\). The totalization must use compatible Koszul signs and boundedness conditions.''','A',r'''The induced derived equivalence is \citet[Theorem~2]{bernsteingelfandgelfand1978bundles}; the notebook's explicit signs are not an exact formula-level match.''',['bernsteingelfandgelfand1978bundles'],reconstruction='The full grading/sign convention is reconstructed; the displayed unsigned expression is not endorsed as a chain differential.',literal='correct with missing hypotheses')
item(438,'P000761','claim','The unit comparison and its erroneous value at one',r'''A natural quasi-isomorphism \(i\to GF\) is asserted. Its displayed value is \(\varphi(v)(1)=\sum x_i\otimes\xi_i v\); for the one-dimensional trivial module the target is said to be the Koszul complex.''',r'''The Koszul adjunction has a natural unit represented, in compatible conventions, by the action map \(v\mapsto[\lambda\mapsto\lambda v]\), including the degree-zero component \(1\mapsto1\otimes v\). The notebook's value alone is zero on a nonzero trivial module and therefore cannot induce the claimed cohomology isomorphism.''','A',r'''The equivalence is established in \citet[Theorem~2]{bernsteingelfandgelfand1978bundles}; the scanned formula is a faithful notebook error.''',['bernsteingelfandgelfand1978bundles'],literal='false as written',reconstruction='The repair specifies the essential nonzero constant component; it is not a full reconstruction of every grading convention.',match='partial')
item(438,'P000761-P000762','definition','Quasi-isomorphisms and the derived category',r'''Complexes, commuting chain maps, cohomology, and quasi-isomorphisms are defined; \(D(A)\) is obtained by inverting quasi-isomorphisms.''',r'''For an abelian category \(\mathcal A\), the derived category is the localization \(K(\mathcal A)[S^{-1}]\) of the homotopy category at quasi-isomorphisms, with a chosen boundedness convention. Objects are complexes and cohomology sends quasi-isomorphisms to isomorphisms.''','E',r'''The notebook itself cites \citet[Chapter~I]{hartshorne1966residues}, published 1966, and Verdier's earlier work.''',['hartshorne1966residues'],verification='publisher metadata checked',reconstruction='The intermediate homotopy category and size conventions are made explicit; strict maps alone do not support the naive Ore formulas.')
item(438,'P000761-P000762','method','Roofs, Ore squares, and cancellation',r'''Morphisms are roofs \(X\leftarrow Z\to Y\); common refinements identify roofs. Composition closure, Ore squares, and cancellation are listed.''',r'''In the homotopy category of complexes, quasi-isomorphisms admit a calculus of fractions: roofs are identified by common refinements commuting up to homotopy. Identity maps belong to the multiplicative system. An arbitrary chain of refinements is not itself a morphism or a substitute for the equivalence relation.''','E',r'''The established localization framework is the one cited in \citet[Chapter~I]{hartshorne1966residues}.''',['hartshorne1966residues'],verification='publisher metadata checked',reconstruction='The notebook suppresses homotopies and identity axioms; these are necessary for its purported precise definition.')
item(438,'P000762','method','Reduction of Koszul comparisons by finite filtrations',r'''Check the natural comparison on the one-dimensional trivial module, then introduce filtrations with standard factors.''',r'''A finite graded exterior module has a finite filtration with one-dimensional trivial graded quotients. If two exact functors and their natural transformation preserve the relevant triangles, the quasi-isomorphism statement extends from such quotients by the long exact cohomology sequence.''','A',r'''This is a proof method for the correspondence of \citet[Theorem~2]{bernsteingelfandgelfand1978bundles}, not an additional open problem.''',['bernsteingelfandgelfand1978bundles'],literal='correct with missing hypotheses',match='partial',reconstruction='Exactness of the functors and the finite filtration are the hypotheses implicit in the proof strategy.')
correction('P000754','regular-module example','free modules lead to trivial bundles','free modules lead to the zero bundle','The same paragraph computes all evaluation homology as zero; a positive-rank trivial bundle is different.',kind='ambiguity')
correction('P000756','Serre bibliography','1953','1955 for Faisceaux algebriques coherents','Opened original Serre publication metadata and text; the quoted projective sheaf theorem belongs to FAC1955.')
correction('P000759','section-module inverse','direct sum over all integers is finitely generated','use sufficiently high nonnegative truncation for an arbitrary coherent sheaf','A skyscraper sheaf has nonzero global sections in every negative twist; this cannot be generated in finitely many graded degrees.')
correction('P000760','total differential','d=partial+sum xi_i x_i with no sign','insert the usual degree-dependent totalization sign or state anticommuting conventions','Scan shows plus only; commuting differentials give cross term2 partial d in characteristic zero.')
